httplib::Server svr;
svr.Get("/orders", [](const httplib::Request& req, httplib::Response& res) {
    if (!require_login(req, res)) return;                // shared, called per page
    res.set_content(render_orders(list_orders(req)),     // view selection
                    "text/html; charset=utf-8");
});
svr.Post("/orders", [](const httplib::Request& req, httplib::Response& res) {
    place_order(parse_order(req.body));                  // domain logic
    res.status = 303;
    res.set_header("Location", "/orders");              // POST-redirect-GET
});
svr.listen("0.0.0.0", 8080);
